CREATE OR REPLACE FUNCTION public.is_active_staff()
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT auth.uid() IS NOT NULL AND EXISTS (
    SELECT 1 FROM public.employees e
    WHERE lower(e.email) = lower(auth.jwt()->>'email')
      AND coalesce(e.disabled,false) = false
      AND lower(coalesce(e.status,'active')) NOT IN ('inactive','terminated','disabled','suspended')
  )
$$;
REVOKE ALL ON FUNCTION public.is_active_staff() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.is_active_staff() TO authenticated, service_role;

DO $$
DECLARE r record; s text;
BEGIN
  FOR r IN
    SELECT p.schemaname, p.tablename, p.policyname, p.qual, p.with_check
    FROM pg_policies p
    JOIN (VALUES
('public.agent_payment_slips','Signed-in staff view slips'), ('public.attendance_import_batches','Staff can view import batches'), ('public.attendance_import_rows','Staff can view import rows'), ('public.batch_number_counters','Staff can view batch counters'), ('public.budget_seasons','Anyone auth can view seasons'), ('public.coffee_booking_deliveries','Allow insert to coffee_booking_deliveries'), ('public.coffee_booking_deliveries','Authenticated read coffee_booking_deliveries'), ('public.daily_reports','Authenticated can view daily_reports'), ('public.defect_library','Authenticated users can update defect_library'), ('public.delivery_routes','Authenticated users can update routes'), ('public.delivery_routes','Authenticated users can view routes'), ('public.dispatch_monitoring_forms','dmf_insert_authenticated'), ('public.eudr_dispatch_reports','Authenticated can view dispatch reports'), ('public.excel_loyalty_rows','Authenticated can view excel loyalty rows'), ('public.excel_loyalty_scans','Authenticated can view excel loyalty scans'), ('public.farmer_profiles','Authenticated users can insert farmer_profiles'), ('public.field_agents','Authenticated can view field_agents'), ('public.field_assessment_prices','Authenticated users can view all assessment prices'), ('public.field_assessments','Authenticated users can view all field assessments'), ('public.field_attendance_logs','Authenticated can view field_attendance_logs'), ('public.field_attendance_logs','Authenticated users can update field_attendance_logs'), ('public.fuel_voucher_counters','Authenticated can view voucher counters'), ('public.fuel_vouchers','Authenticated can update fuel vouchers'), ('public.grn_pay_codes','Authenticated can create grn pay codes'), ('public.grn_payment_allocations','Staff can view GRN referrals'), ('public.grn_print_log','Authenticated can read grn print log'), ('public.inventory_batch_sales','Authenticated users can view batch sales'), ('public.inventory_batch_sources','Authenticated users can view batch sources'), ('public.inventory_batches','Authenticated users can view inventory batches'), ('public.inventory_movements','Users can create inventory movements'), ('public.inventory_movements','Users can view inventory movements'), ('public.market_intelligence_reports','Authenticated users can read market intelligence reports'), ('public.market_reports','Authenticated users can view market reports'), ('public.metrics','Authenticated users can view metrics'), ('public.payment_receipt_prints','Authenticated can update receipt prints'), ('public.price_data','Authenticated users can view price data'), ('public.price_history','Anyone can view price history'), ('public.procurement_reviews','Authenticated can view procurement reviews'), ('public.quality_analysis_files','Authenticated can view quality analysis files'), ('public.quality_analysis_forms','Authenticated can view analysis forms'), ('public.quality_daily_checklists','Authenticated users can update quality_daily_checklists'), ('public.quality_daily_checklists','Authenticated users can view quality_daily_checklists'), ('public.quality_dispatch_analyses','Staff can create dispatch analyses'), ('public.quality_form_numbers','Authenticated can view form numbers'), ('public.quality_manager_approvals','Staff can view quality manager approvals'), ('public.quality_performance_tracking','Authenticated users can update quality_performance_tracking'), ('public.quality_performance_tracking','Authenticated users can view quality_performance_tracking'), ('public.quality_recommendations','Authenticated users can update quality_recommendations'), ('public.quality_recommendations','Authenticated users can view quality_recommendations'), ('public.quality_reevaluations','Authenticated users can view quality_reevaluations'), ('public.quality_sampling_orders','Lab staff can update sampling orders'), ('public.sales_inventory_tracking','Authenticated users can view sales tracking'), ('public.scheduled_meetings','Authenticated can view scheduled meetings'), ('public.store_delivery_verifications','Signed-in staff can view store verifications'), ('public.store_records','Authenticated can view store records'), ('public.store_report_form_numbers','Signed-in staff can view store form numbers'), ('public.store_reports','Authenticated users can update store_reports'), ('public.store_reports','Authenticated users can view store_reports'), ('public.store_weighing_tickets','Staff view weighing tickets'), ('public.support_tickets','Authenticated staff can insert tickets'), ('public.system_console_logs','Anyone can log console messages'), ('public.system_errors','Authenticated can insert system errors'), ('public.training_simulations','Authenticated users can view training_simulations'), ('public.ussd_services','Authenticated can view ussd services'), ('public.v3_branches','v3_branches_read'), ('public.v3_export_documents','v3_exportdocs_read'), ('public.v3_export_shipments','v3_shipments_read'), ('public.v3_grns','v3_grns_read'), ('public.v3_production_runs','v3_production_read'), ('public.v3_quality_analyses','v3_quality_read'), ('public.v3_receiving_records','v3_receiving_read'), ('public.v3_reference_prices','v3_prices_read'), ('public.v3_stock_batches','v3_stock_read'), ('public.v3_suppliers','v3_suppliers_read'), ('public.v3_transfers','v3_transfers_read'), ('public.warehouse_quality_monitoring','Authenticated users can view warehouse_quality_monitoring'), ('public.warehouses','Authenticated users can update warehouses'), ('public.weekly_reports','Authenticated can view weekly_reports'), ('public.weighbridge_scan_sessions','Authenticated can create sessions'), ('storage.objects','Authenticated can delete clearance form scans'), ('storage.objects','Authenticated can update clearance form scans'), ('storage.objects','Authenticated can upload clearance form scans'), ('storage.objects','Authenticated can view clearance form scans'), ('storage.objects','Authenticated users can upload CVs'), ('storage.objects','Authenticated users can view market screenshots'), ('storage.objects','Signed-in staff can view profile pictures'), ('storage.objects','Staff can upload report documents')
    ) AS v(t, pn) ON v.t = p.schemaname || '.' || p.tablename AND v.pn = p.policyname
  LOOP
    s := format('ALTER POLICY %I ON %I.%I', r.policyname, r.schemaname, r.tablename);
    IF r.qual IS NOT NULL AND r.with_check IS NOT NULL THEN
      s := s || format(' USING ((%s) AND public.is_active_staff()) WITH CHECK ((%s) AND public.is_active_staff())', r.qual, r.with_check);
    ELSIF r.qual IS NOT NULL THEN
      s := s || format(' USING ((%s) AND public.is_active_staff())', r.qual);
    ELSE
      s := s || format(' WITH CHECK ((%s) AND public.is_active_staff())', r.with_check);
    END IF;
    EXECUTE s;
  END LOOP;
END $$;